css:
.loader {
  position: relative;
  width: 48px;
  height: 44px;
}
.loader::before {
  content: "";
  position: absolute;
  top: 6px;
  left: 6px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #6366f1;
  box-shadow: 30px 0 0 #6366f1;
}
.loader i {
  position: absolute;
  top: 9px;
  left: 9px;
  width: 30px;
  height: 32px;
  border: 3px solid #6366f1;
  border-radius: 50%;
  box-sizing: border-box;
  transform-origin: top center;
  animation: rope 0.7s ease-in-out infinite;
}
@keyframes rope {
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(0.12); }
}
